def test_a_collection_read_is_a_get_with_the_cmdlets_query_options(
    auth: AuthContext,
) -> None:
    recorder = Recorder([ok({"value": [{"Alias": "a"}]}, headers={"X-Warnings": "slow"})])
    with ExchangeClient(auth, page_size=50, transport=recorder.transport) as exchange:
        result = exchange.mailboxes(
            PropertySet="Audit",
            RecipientTypeDetails=["UserMailbox", "SharedMailbox"],
            select=["DefaultAuditSet", "UserPrincipalName"],
            IncludeInactiveMailbox=True,
        )

    request = recorder.requests[0]
    assert result == [{"Alias": "a"}]
    assert exchange.last_warnings == ["slow"]
    assert request.method == "GET"
    # On the wire as the PowerShell module sends it: "$" and "," unescaped.
    assert str(request.url) == (
        f"{ROOT}/Mailbox?$select=DefaultAuditSet,UserPrincipalName&PropertySet=Audit"
        "&RecipientTypeDetails=UserMailbox,SharedMailbox&IncludeInactiveMailbox=True"
    )
    assert not request.content
    assert request.headers["X-AnchorMailbox"] == f"UPN:{USER}"
    assert request.headers["Prefer"] == "odata.maxpagesize=50"
    assert request.headers["Content-Type"] == "application/json;odata.metadata=minimal"
    assert "X-CmdletName" not in request.headers
    assert len(request.headers["connection-id"]) == len(request.headers["client-request-id"]) == 36


