def test_paging_gets_each_next_link_without_a_body(auth: AuthContext) -> None:
    next_link = f"{ROOT}/Mailbox?$skiptoken=page2"
    pages = [
        ok({"value": [{"n": 1}], "@odata.nextLink": next_link}),
        ok({"value": [{"n": 2}], "@adminapi.warnings": ["late"]}),
    ]
    recorder = Recorder(pages)
    exchange = ExchangeClient(auth, transport=recorder.transport)

    assert exchange.mailboxes() == [{"n": 1}, {"n": 2}]

    assert [(r.method, str(r.url)) for r in recorder.requests] == [
        ("GET", f"{ROOT}/Mailbox"),
        ("GET", next_link),
    ]
    assert not any(r.content for r in recorder.requests)
    assert (
        recorder.requests[0].headers["connection-id"]
        == (recorder.requests[1].headers["connection-id"])
    )
    assert exchange.last_warnings == ["late"]


