def test_a_failed_read_quotes_the_odata_error(auth: AuthContext) -> None:
    body = {"error": {"code": "BadRequest", "message": "Could not find a property named 'Foo'"}}
    exchange = ExchangeClient(auth, transport=Recorder([ok(body, 400)]).transport)

    with pytest.raises(InvokeCommandError) as caught:
        exchange.mailboxes(select="Foo")

    error = caught.value
    assert (error.status, error.code, error.body) == (400, "BadRequest", body)
    assert str(error) == (
        f"GET {ROOT}/Mailbox?$select=Foo -> 400 BadRequest: Could not find a property named 'Foo'"
    )


def test_a_failed_read_with_details_leads_with_them(auth: AuthContext) -> None:
    body = {
        "error": {
            "code": "NotFound",
            "message": "Error executing request",
            "details": [{"message": "Ex1|SomeException|The mailbox 'x' is not there."}],
        }
    }
    exchange = ExchangeClient(auth, transport=Recorder([ok(body, 404)]).transport)

    with pytest.raises(InvokeCommandError) as caught:
        exchange.mailboxes("x")

    message = str(caught.value)
    assert message.startswith(
        f"GET /adminapi/beta/{TENANT_GUID}/Mailbox('eA==') failed: The mailbox 'x' is not there."
    )
    assert "-> 404 NotFound: Error executing request" in message


def test_a_read_follows_the_regional_redirect_with_its_token(auth: AuthContext) -> None:
    home = "outlook.office365.com"
    regional = f"nam12.{home}"

    def handler(request: httpx.Request) -> httpx.Response:
        if request.url.host == home:
            return httpx.Response(302, headers={"Location": f"https://{regional}/adminapi/x"})
        return ok({"value": [{"n": 1}]})

    recorder = Recorder(handler)
    exchange = ExchangeClient(auth, transport=recorder.transport)

    assert exchange.mailboxes(PropertySet="Minimum") == [{"n": 1}]

    assert [r.url.host for r in recorder.requests] == [home, regional]
    assert all(r.method == "GET" for r in recorder.requests)
    assert all(r.headers["Authorization"].startswith("Bearer ") for r in recorder.requests)
    assert recorder.requests[1].url.path == f"/adminapi/beta/{TENANT_GUID}/Mailbox"
    assert dict(recorder.requests[1].url.params) == {"PropertySet": "Minimum"}
    assert exchange.base_url == f"https://{regional}"


def test_reads_route_like_cmdlets(auth: AuthContext) -> None:
    app = AuthContext("contoso.onmicrosoft.com", client_id="app", client_secret="s3cret")
    sibling = auth.for_tenant("managed.onmicrosoft.com")
    recorder = Recorder(lambda request: ok({"value": []}))

    ExchangeClient(app, transport=recorder.transport).mailboxes()
    ExchangeClient(sibling, transport=recorder.transport).mailboxes()
    ExchangeClient(
        auth, anchor_mailbox="UPN:shared@partner.com", transport=recorder.transport
    ).mailboxes()

    assert [r.headers["X-AnchorMailbox"] for r in recorder.requests] == [
        f"APP:{SYSTEM_MAILBOX}@{TENANT_GUID}",
        f"APP:{SYSTEM_MAILBOX}@{TENANT_GUID}",
        "UPN:shared@partner.com",
    ]
